//! hexcrypt-core: the encryption layer shared by the hexcrypt CLI and the web client.
//!
//! Threat model: the server stores only `blob`. The 256-bit key is generated by the
//! client and travels in the URL fragment, which browsers never send to servers.
//! The secret id is used as AEAD associated data so a blob cannot be re-homed
//! under a different id.
//!
//! Wire format of `blob`: `VERSION(1) || nonce(24) || ciphertext+tag`.
//! Plaintext envelope: `kind(1) || name_len(2, LE) || name || data`.

use base64::Engine;
use chacha20poly1305::aead::{Aead, KeyInit, Payload};
use chacha20poly1305::{XChaCha20Poly1305, XNonce};

pub const KEY_LEN: usize = 32;
pub const NONCE_LEN: usize = 24;
/// Secret ids are 12 lowercase hex chars (48 random bits).
pub const ID_LEN: usize = 12;
const VERSION: u8 = 1;

#[derive(Debug, PartialEq, Eq)]
pub enum Error {
    Rng,
    BadKey,
    BadId,
    BadUrl,
    BadBlob,
    Decrypt,
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Error::Rng => "random number generator unavailable",
            Error::BadKey => "key is not 32 bytes of base64url",
            Error::BadId => "id must be 12 hex characters",
            Error::BadUrl => "url must look like https://host/<id>#<key>",
            Error::BadBlob => "blob is malformed",
            Error::Decrypt => "decryption failed: wrong key, wrong id, or tampered data",
        })
    }
}
impl std::error::Error for Error {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum Kind {
    Text = 0,
    File = 1,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Envelope {
    pub kind: Kind,
    pub name: String,
    pub data: Vec<u8>,
}

impl Envelope {
    pub fn text(s: &str) -> Self {
        Envelope { kind: Kind::Text, name: String::new(), data: s.as_bytes().to_vec() }
    }
    pub fn file(name: &str, data: Vec<u8>) -> Self {
        Envelope { kind: Kind::File, name: name.to_string(), data }
    }
    pub fn to_bytes(&self) -> Vec<u8> {
        let name = self.name.as_bytes();
        let name_len = name.len().min(u16::MAX as usize);
        let mut out = Vec::with_capacity(3 + name_len + self.data.len());
        out.push(self.kind as u8);
        out.extend_from_slice(&(name_len as u16).to_le_bytes());
        out.extend_from_slice(&name[..name_len]);
        out.extend_from_slice(&self.data);
        out
    }
    pub fn from_bytes(b: &[u8]) -> Result<Self, Error> {
        if b.len() < 3 {
            return Err(Error::BadBlob);
        }
        let kind = match b[0] {
            0 => Kind::Text,
            1 => Kind::File,
            _ => return Err(Error::BadBlob),
        };
        let name_len = u16::from_le_bytes([b[1], b[2]]) as usize;
        let rest = &b[3..];
        if rest.len() < name_len {
            return Err(Error::BadBlob);
        }
        let name = String::from_utf8(rest[..name_len].to_vec()).map_err(|_| Error::BadBlob)?;
        Ok(Envelope { kind, name, data: rest[name_len..].to_vec() })
    }
}

fn random(buf: &mut [u8]) -> Result<(), Error> {
    getrandom::fill(buf).map_err(|_| Error::Rng)
}

pub fn new_key() -> Result<[u8; KEY_LEN], Error> {
    let mut k = [0u8; KEY_LEN];
    random(&mut k)?;
    Ok(k)
}

pub fn new_id() -> Result<String, Error> {
    let mut b = [0u8; ID_LEN / 2];
    random(&mut b)?;
    Ok(b.iter().map(|x| format!("{x:02x}")).collect())
}

pub fn is_valid_id(id: &str) -> bool {
    id.len() == ID_LEN && id.bytes().all(|c| matches!(c, b'0'..=b'9' | b'a'..=b'f'))
}

const B64: base64::engine::GeneralPurpose = base64::engine::general_purpose::URL_SAFE_NO_PAD;

pub fn encode_key(key: &[u8; KEY_LEN]) -> String {
    B64.encode(key)
}

pub fn decode_key(s: &str) -> Result<[u8; KEY_LEN], Error> {
    let v = B64.decode(s.trim()).map_err(|_| Error::BadKey)?;
    v.try_into().map_err(|_| Error::BadKey)
}

pub fn encrypt(id: &str, key: &[u8; KEY_LEN], plaintext: &[u8]) -> Result<Vec<u8>, Error> {
    if !is_valid_id(id) {
        return Err(Error::BadId);
    }
    let mut nonce = [0u8; NONCE_LEN];
    random(&mut nonce)?;
    let cipher = XChaCha20Poly1305::new(key.into());
    let ct = cipher
        .encrypt(&XNonce::from(nonce), Payload { msg: plaintext, aad: id.as_bytes() })
        .map_err(|_| Error::Decrypt)?;
    let mut out = Vec::with_capacity(1 + NONCE_LEN + ct.len());
    out.push(VERSION);
    out.extend_from_slice(&nonce);
    out.extend_from_slice(&ct);
    Ok(out)
}

pub fn decrypt(id: &str, key: &[u8; KEY_LEN], blob: &[u8]) -> Result<Vec<u8>, Error> {
    if !is_valid_id(id) {
        return Err(Error::BadId);
    }
    if blob.len() < 1 + NONCE_LEN + 16 || blob[0] != VERSION {
        return Err(Error::BadBlob);
    }
    let (nonce, ct) = blob[1..].split_at(NONCE_LEN);
    let nonce = XNonce::try_from(nonce).map_err(|_| Error::BadBlob)?;
    let cipher = XChaCha20Poly1305::new(key.into());
    cipher
        .decrypt(&nonce, Payload { msg: ct, aad: id.as_bytes() })
        .map_err(|_| Error::Decrypt)
}

/// `https://hexcrypt.com` + `3fa9c2e17b04` + key -> `https://hexcrypt.com/3fa9c2e17b04#<key>`
pub fn build_url(base: &str, id: &str, key: &[u8; KEY_LEN]) -> String {
    format!("{}/{}#{}", base.trim_end_matches('/'), id, encode_key(key))
}

/// Inverse of [`build_url`]. Returns `(base, id, key)`.
pub fn parse_url(url: &str) -> Result<(String, String, [u8; KEY_LEN]), Error> {
    let (path, frag) = url.trim().split_once('#').ok_or(Error::BadUrl)?;
    let (base, id) = path.trim_end_matches('/').rsplit_once('/').ok_or(Error::BadUrl)?;
    if !is_valid_id(id) || !base.contains("://") {
        return Err(Error::BadUrl);
    }
    Ok((base.to_string(), id.to_string(), decode_key(frag)?))
}

#[cfg(feature = "wasm")]
mod wasm;

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn roundtrip_text_and_file() {
        for env in [Envelope::text("hi there"), Envelope::file("a.bin", vec![0, 1, 2, 255])] {
            let id = new_id().unwrap();
            let key = new_key().unwrap();
            let blob = encrypt(&id, &key, &env.to_bytes()).unwrap();
            let pt = decrypt(&id, &key, &blob).unwrap();
            assert_eq!(Envelope::from_bytes(&pt).unwrap(), env);
        }
    }

    #[test]
    fn tamper_wrong_key_wrong_id_fail() {
        let id = new_id().unwrap();
        let key = new_key().unwrap();
        let mut blob = encrypt(&id, &key, b"secret").unwrap();
        assert_eq!(decrypt(&new_id().unwrap(), &key, &blob), Err(Error::Decrypt));
        assert_eq!(decrypt(&id, &new_key().unwrap(), &blob), Err(Error::Decrypt));
        let last = blob.len() - 1;
        blob[last] ^= 1;
        assert_eq!(decrypt(&id, &key, &blob), Err(Error::Decrypt));
        assert_eq!(decrypt(&id, &key, &blob[..10]), Err(Error::BadBlob));
        assert_eq!(encrypt("nothex", &key, b"x"), Err(Error::BadId));
    }

    #[test]
    fn url_roundtrip() {
        let key = new_key().unwrap();
        let url = build_url("https://hexcrypt.com/", "3fa9c2e17b04", &key);
        assert_eq!(url, format!("https://hexcrypt.com/3fa9c2e17b04#{}", encode_key(&key)));
        let (base, id, k) = parse_url(&url).unwrap();
        assert_eq!((base.as_str(), id.as_str(), k), ("https://hexcrypt.com", "3fa9c2e17b04", key));
        assert_eq!(parse_url("https://x/3fa9c2e17b04").unwrap_err(), Error::BadUrl);
        assert_eq!(parse_url("https://x/short#abc").unwrap_err(), Error::BadUrl);
        assert_eq!(parse_url("https://x/3fa9c2e17b04#abc").unwrap_err(), Error::BadKey);
    }

    #[test]
    fn envelope_rejects_garbage() {
        assert_eq!(Envelope::from_bytes(&[]), Err(Error::BadBlob));
        assert_eq!(Envelope::from_bytes(&[9, 0, 0]), Err(Error::BadBlob));
        assert_eq!(Envelope::from_bytes(&[1, 5, 0, b'a']), Err(Error::BadBlob));
    }
}
